	minLoad := snapshots[0].EffectiveLoad()
	totalLoad := 0
	maxFree := int64(1)
	for _, snap := range snapshots {
		ld := snap.EffectiveLoad()
		if ld > maxLoad {
			maxLoad = ld
		}
		if ld < minLoad {
			minLoad = ld
		}
		totalLoad += ld
		if snap.FreeKVBlocks > maxFree {
			maxFree = snap.FreeKVBlocks
		}
	}
	loadSpread := maxLoad - minLoad
	avgLoad := float64(totalLoad) / float64(len(snapshots))

