	prefixW := ws.weights[0]
	loadW := ws.weights[1]
	if len(ws.weights) >= 2 {
		spreadFactor := float64(loadSpread) / (float64(loadSpread) + 2.0)
		prefixW = ws.weights[0] * (1.0 - 0.7*spreadFactor)
		loadW = ws.weights[1] * (1.0 + 1.8*spreadFactor)
	}
	adaptiveWeights := make([]float64, len(ws.weights))
