	minLoad := snapshots[0].EffectiveLoad()
	totalLoad := 0
	maxFree := int64(1)
	for _, snap := range snapshots {
		ld := snap.EffectiveLoad()
		if ld > maxLoad {
			maxLoad = ld
		}
		if ld < minLoad {
			minLoad = ld
		}
		totalLoad += ld
		if snap.FreeKVBlocks > maxFree {
			maxFree = snap.FreeKVBlocks
		}
	}
	loadSpread := maxLoad - minLoad
	avgLoad := float64(totalLoad) / float64(len(snapshots))

	// Simplified adaptive weights: binary shift based on load imbalance
	adaptiveWeights := make([]float64, len(ws.weights))
	copy(adaptiveWeights, ws.weights)
	if len(ws.weights) >= 2 && loadSpread > 2 {
		// Load imbalance detected: strongly favor load balancing
		adaptiveWeights[0] = ws.weights[0] * 0.4
		adaptiveWeights[1] = ws.weights[1] * 2.2
	}

